  el('reading-add-feed').addEventListener('click',()=>{returnFocus=document.activeElement;closeOptions();el('reading-feed-error').hidden=true;el('reading-feed-url').value='';el('reading-site-selector').value='';setAddMode('page');el('reading-feed-form').hidden=false;el('reading-feed-url').focus()});el('reading-feed-cancel').addEventListener('click',closeForm);
